var i=`0695-akassa`;var r=`world-0695`;var n=`BJ`;var a=`western-africa`;var s=8;var o=528;var d={en:`Akassa`,ua:`Акасса`};var l={en:`Akassa is a Benin classic prepared with cornmeal, sourdough starter, peanut sauce. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Akassa-style fermented corn porridge from pantry cornmeal and a yogurt-assisted dough; true fermented maize dough differs.`,ua:`Акасса, страва кухні країни Бенін зі складниками: кукурудзяна крупа дрібного помелу, хлібна закваска, арахісовий соус. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Каша у стилі акасса з кукурудзяного борошна та легкої йогуртової ферментації; справжня ферментована основа інша.`};var m=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`cornmeal`,300,`g`],[`water`,480,`ml`],[`sourdough-starter`,40,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 480 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 480 хвилин.`,t:[`rapid-chilling`],m:480,i:[]},{en:`Steam small covered parcels or heatproof ramekins of the fermented cornmeal mixture until completely set; serve warm.`,ua:`Пропарте невеликі закриті порції ферментованої кукурудзяної маси в листі або формочках до повної готовності; подавайте теплими.`,t:[`steaming`],m:35,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut-sauce`,180,`g`]]}];var u={slug:i,id:r,country:`BJ`,region:a,servings:8,minutes:528,title:d,text:l,steps:m};export{n as country,u as default,r as id,o as minutes,a as region,s as servings,i as slug,m as steps,l as text,d as title};